__cast(field){
    const isColumns = Array.isArray(this.options.columns)
    if( isColumns === true && this.options.columns.length <= this.state.record.length ){
      return [undefined, undefined]
    }
    const context = {
      column: isColumns === true ?
        this.options.columns[this.state.record.length].name :
        this.state.record.length,
      empty_lines: this.info.empty_lines,
      header: this.options.columns === true,
      index: this.state.record.length,
      invalid_field_length: this.info.invalid_field_length,
      quoting: this.state.wasQuoting,
      lines: this.info.lines,
      records: this.info.records
    }
    if(this.state.castField !== null){
      try{
        return [undefined, this.state.castField.call(null, field, context)]
      }catch(err){
        return [err]
      }
    }
    if(this.__isInt(field) === true){
      return [undefined, parseInt(field)]
    }else if(this.__isFloat(field)){
      return [undefined, parseFloat(field)]
    }else if(this.options.cast_date !== false){
      return [undefined, this.options.cast_date.call(null, field, context)]
    }
    return [undefined, field]
  }

constructor(authUrl, username, password) {
        super();

        let url;
        let token;

        let authStatus = AUTH_STATUS.UNAUTHENTICATED;
        let authError = null;

        requestp({
            method: 'GET',
            uri: authUrl,
            headers: {
                'x-auth-user': username,
                'x-auth-key': password
            },
            resolveWithFullResponse: true
        }).then(response => {
            url = response.headers['x-storage-url'];
            token = response.headers['x-auth-token'];
            authStatus = AUTH_STATUS.AUTHENTICATED;
            this.emit(AUTH_EVENT);
        }).catch(err => {
            authStatus = AUTH_STATUS.FAILED;
            authError = err;
            this.emit(AUTH_EVENT);
        });

        this._authenticate = function () {
            let returnPromise;
            switch (authStatus) {
                case AUTH_STATUS.UNAUTHENTICATED:
                    returnPromise = new Promise((resolve, reject) => {
                        const authListener = () => {
                            this.removeListener(AUTH_EVENT, authListener);
                            if (authStatus === AUTH_STATUS.AUTHENTICATED) resolve({url: url, token: token});
                            if (authStatus === AUTH_STATUS.FAILED) reject(authError);
                        };

                        this.on(AUTH_EVENT, authListener);
                    });
                    break;
                case AUTH_STATUS.AUTHENTICATED:
                    returnPromise = new Promise(resolve => {
                        resolve({url: url, token: token});
                    });
                    break;
                case AUTH_STATUS.FAILED:
                    returnPromise = new Promise((resolve, reject) => {
                        reject(authError);
                    });
                    break;
            }

            return returnPromise;
        }
    }

function createObjectIterator(obj) {
    var okeys = obj ? Object.keys(obj) : [];
    var i = -1;
    var len = okeys.length;
    return function next() {
        var key = okeys[++i];
        if (key === '__proto__') {
            return next();
        }
        return i < len ? {value: obj[key], key} : null;
    };
}

