function getEspeakCmdWithArgs(fields) {

	var text = fields.textToSpeech,
		language = fields.language,
		voiceCode = '+f4',
		voice = language + voiceCode,
		speed = Math.floor(fields.speed * 150),
		pitch = '70';

	return {
		cmd: 'espeak',
		args: [
			'-v', voice,
			'-s', speed,
			'-p', pitch,
			text
		]
	};
